rows = []; fl = []
def sha(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(1 << 22), b""): h.update(b)
    return h.hexdigest()
cache = {}
for d in D:
    p = d["local_path"]; size = ""; digest = ""
    if p != "-":
        files = [q for q in ([p] if os.path.isfile(p) else sorted(glob.glob(p + "/**/*", recursive=True))) if os.path.isfile(q)] if os.path.exists(p) else []
        if d["status"] == "script_only": files = [q for q in files if os.path.basename(q).startswith(("tile_manifest", "lidar_workunits"))] if os.path.isdir(p) else files
        if os.path.isdir(p) and d["name"].startswith("USGS 3DEP lidar workunit"): files = sorted(glob.glob(p + "/lidar_workunits_*.csv"))
        if d["name"].startswith("3DEP 1/3"): files = sorted(glob.glob(p + "/*.tif"))
        if d["name"].startswith("3DEP 1 m"): files = [p, p.replace("tile_manifest", "lidar_workunits_A")]
        files = [q for q in files if os.path.exists(q)]
        hs = []
        for q in files:
            if q not in cache: cache[q] = (os.path.getsize(q), sha(q))
            hs.append(cache[q][1]); fl.append(dict(dataset=d["name"], path=q.replace("\\", "/"), bytes=cache[q][0], sha256=cache[q][1]))
        size = sum(cache[q][0] for q in files) if files else ""
        digest = hashlib.sha256("".join(sorted(hs)).encode()).hexdigest() if len(hs) > 1 else (hs[0] if hs else "")
    d["file_size_bytes"] = size; d["sha256"] = digest
cols = ["name", "area", "source_url", "original_filename", "local_path", "coverage", "date_vintage", "crs_vertical_datum", "license", "key_fields", "file_size_bytes", "sha256", "status", "notes"]
with open("data/inventory/datasets.csv", "w", newline="", encoding="utf-8") as f:
    w = csv.DictWriter(f, fieldnames=cols); w.writeheader(); [w.writerow({c: d[c] for c in cols}) for d in D]
with open("data/inventory/sha256_files.csv", "w", newline="", encoding="utf-8") as f:
    w = csv.DictWriter(f, fieldnames=["dataset", "path", "bytes", "sha256"]); w.writeheader(); w.writerows(fl)
print(len(D), "datasets;", len(fl), "files hashed;", sum(1 for d in D if d["status"] == "downloaded"), "downloaded")
